"""Deterministic algorithm traces generated by Python, independent of the LLM."""
from copy import deepcopy
from dataclasses import asdict, dataclass
from core.exceptions import ValidationError


@dataclass(frozen=True)
class AlgorithmStep:
    step_index: int
    operation: str
    state: dict
    description: str
    highlighted_elements: list


class Trace:
    def __init__(self):
        self.steps = []

    def add(self, operation, state, description, highlights=None):
        self.steps.append(AlgorithmStep(len(self.steps), operation, deepcopy(state), description, highlights or []))

    def output(self):
        return [asdict(step) for step in self.steps]


def linked_list_steps(values):
    trace = Trace()
    state = {"values": list(values), "links": [i + 1 if i + 1 < len(values) else None for i in range(len(values))],
             "prev": None, "curr": 0 if values else None, "next": None, "head": 0 if values else None}
    trace.add("initialize", state, "prev 为空，curr 指向原表头；维护已反转前缀与未处理后缀。")
    while state["curr"] is not None:
        current = state["curr"]
        state["next"] = state["links"][current]
        trace.add("save_next", state, "先保存原后继，防止反转指针后丢失剩余链表。", [current])
        state["links"][current] = state["prev"]
        trace.add("reverse_link", state, "将 curr.next 改为 prev。", [current, state["prev"]])
        state["prev"], state["curr"] = current, state["next"]
        trace.add("advance", state, "prev 前进到当前节点，curr 前进到原后继。", [state["prev"], state["curr"]])
    state["head"] = state["prev"]
    trace.add("done", state, "curr 为空，prev 成为新表头；时间 O(n)，辅助空间 O(1)。")
    return trace.output()


def next_array(pattern):
    if not pattern:
        return []
    result = [-1] * len(pattern)
    i, j = 0, -1
    while i < len(pattern) - 1:
        if j == -1 or pattern[i] == pattern[j]:
            i, j = i + 1, j + 1
            result[i] = j
        else:
            j = result[j]
    return result


def string_steps(text, pattern, algorithm="kmp"):
    trace = Trace()
    nxt = next_array(pattern) if algorithm == "kmp" else []
    state = {"text": text, "pattern": pattern, "i": 0, "j": 0, "next": nxt, "comparisons": 0, "match_index": None, "algorithm": algorithm}
    trace.add("initialize", state, "字符下标从 0 开始；KMP next[0] = -1。" if algorithm == "kmp" else "BF 失配时回溯主串起点，并重置模式串指针。")
    if not pattern:
        state["match_index"] = 0
        trace.add("done", state, "空模式串约定匹配位置为 0。")
        return trace.output()
    i, j = 0, 0
    while i < len(text) and j < len(pattern):
        if j == -1:
            i, j = i + 1, 0
            state.update(i=i, j=j)
            trace.add("advance", state, "next 指向 -1，主串指针前进，模式从 0 重新比较。")
            continue
        state.update(i=i, j=j, comparisons=state["comparisons"] + 1)
        equal = text[i] == pattern[j]
        state["matched"] = equal
        trace.add("compare", state, f"比较 S[{i}] 与 T[{j}]：{'相等' if equal else '失配'}。", [{"text": i}, {"pattern": j}])
        if equal:
            i, j = i + 1, j + 1
            state.update(i=i, j=j)
            trace.add("advance", state, "两个指针同时前进。")
        elif algorithm == "kmp":
            previous = j
            j = nxt[j]
            state.update(i=i, j=j)
            trace.add("fallback", state, f"模式指针 j 从 {previous} 跳至 next[{previous}] = {j}；主串指针 i 保持不变。")
        else:
            i, j = i - j + 1, 0
            state.update(i=i, j=j)
            trace.add("fallback", state, "主串退回下一候选起点，模式串从头开始。")
    state.update(i=i, j=j, match_index=i - j if j == len(pattern) else -1)
    trace.add("done", state, f"匹配位置 {state['match_index']}，字符比较 {state['comparisons']} 次。")
    return trace.output()


def queue_steps(capacity, operations):
    trace = Trace()
    # Course convention: front is immediately BEFORE the first element; rear is
    # the last element. Reserve one slot to distinguish empty/full consistently.
    state = {"array": [None] * capacity, "capacity": capacity, "front": 0, "rear": 0, "size": 0,
             "empty": True, "full": False, "result": None, "usable_capacity": capacity - 1,
             "convention": "front 指向队头前一格，rear 指向队尾；保留一格"}
    trace.add("initialize", state, "front == rear 为队空；(rear + 1) % capacity == front 为队满。")
    for item in operations:
        operation = item["operation"]
        state["result"] = None
        if operation == "enqueue":
            if state["full"]:
                trace.add("full", state, "队满，拒绝入队；指针与内容不变。")
                continue
            state["rear"] = (state["rear"] + 1) % capacity
            state["array"][state["rear"]] = item.get("value")
            state["size"] += 1
            description = "rear 循环前进一格，在新队尾保存元素。"
        elif operation == "dequeue":
            if state["empty"]:
                trace.add("empty", state, "队空，拒绝出队；指针与内容不变。")
                continue
            state["front"] = (state["front"] + 1) % capacity
            state["result"] = state["array"][state["front"]]
            state["array"][state["front"]] = None
            state["size"] -= 1
            description = "front 循环前进一格，取出该位置的元素。"
        else:
            raise ValidationError("队列操作只支持 enqueue 或 dequeue。")
        state["empty"] = state["front"] == state["rear"]
        state["full"] = (state["rear"] + 1) % capacity == state["front"]
        trace.add(operation, state, description, [state["front"], state["rear"]])
    trace.add("done", state, "全部操作完成；每次入队和出队均为 O(1)。")
    return trace.output()


def stack_steps(capacity, operations):
    trace = Trace()
    state = {"array": [None] * capacity, "capacity": capacity, "top": -1, "size": 0, "empty": True, "full": False, "result": None}
    trace.add("initialize", state, "顺序栈遵循 LIFO，top = -1 表示栈空。")
    for item in operations:
        operation = item["operation"]
        state["result"] = None
        if operation == "push":
            if state["full"]:
                trace.add("full", state, "栈满，拒绝入栈。")
                continue
            state["top"] += 1
            state["array"][state["top"]] = item.get("value")
        elif operation == "pop":
            if state["empty"]:
                trace.add("empty", state, "栈空，拒绝出栈。")
                continue
            state["result"] = state["array"][state["top"]]
            state["array"][state["top"]] = None
            state["top"] -= 1
        else:
            raise ValidationError("栈操作只支持 push 或 pop。")
        state.update(size=state["top"] + 1, empty=state["top"] == -1, full=state["top"] == capacity - 1)
        trace.add(operation, state, "先调整栈顶，再写入元素。" if operation == "push" else "取出栈顶元素，再下移栈顶。", [state["top"]])
    trace.add("done", state, "全部操作完成。")
    return trace.output()


def generate_steps(payload):
    algorithm = payload.get("algorithm", "linked_list")
    if algorithm in ("linked_list", "linked"):
        values = payload.get("values", [1, 2, 3, 4])
        if not isinstance(values, list) or len(values) > 24 or any(not isinstance(value, (int, float, str)) or len(str(value)) > 16 for value in values):
            raise ValidationError("链表最多 24 个短数值或字符。")
        steps = linked_list_steps(values)
    elif algorithm in ("kmp", "bf"):
        text, pattern = payload.get("text", "ababcabcacbab"), payload.get("pattern", "abcac")
        if not isinstance(text, str) or not isinstance(pattern, str) or len(text) > 120 or len(pattern) > 32:
            raise ValidationError("主串长度上限 120，模式串长度上限 32。")
        steps = string_steps(text, pattern, algorithm)
    elif algorithm in ("queue", "stack"):
        capacity, operations = payload.get("capacity", 6), payload.get("operations", [])
        if not isinstance(capacity, int) or not 2 <= capacity <= 20 or not isinstance(operations, list) or len(operations) > 80 or any(not isinstance(item, dict) or not isinstance(item.get("operation"), str) or (item.get("value") is not None and not isinstance(item.get("value"), (int, float, str))) or len(str(item.get("value", ""))) > 16 for item in operations):
            raise ValidationError("容量须为 2–20，操作不超过 80 条，元素为短数值或字符。")
        steps = queue_steps(capacity, operations) if algorithm == "queue" else stack_steps(capacity, operations)
    else:
        raise ValidationError("不支持该算法演示。")
    return {"algorithm": algorithm, "steps": steps, "count": len(steps), "source": "Python确定性算法状态引擎"}
